let currentLang = "en";

function toggleLangMenu(){
  document.getElementById("langMenu").classList.toggle("show");
}
document.addEventListener("click", function(e){
  const box = document.querySelector(".lang-select");
  if(box && !box.contains(e.target)) document.getElementById("langMenu").classList.remove("show");
});

function setLang(lang){
  currentLang = lang;
  document.getElementById("langBtnLabel").textContent = lang.toUpperCase();
  document.querySelectorAll(".lang-option").forEach(o=>o.classList.toggle("selected", o.dataset.lang===lang));
  document.getElementById("langMenu").classList.remove("show");
  applyTranslations();
  renderImportation();
  renderReadyProducts();
  if(!document.getElementById("view-admin").classList.contains("hidden")) renderAdminTable();
  document.documentElement.lang = lang;
}

function applyTranslations(){
  const dict = I18N[currentLang];
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const key = el.getAttribute("data-i18n");
    if(dict[key] !== undefined) el.textContent = dict[key];
  });
  document.querySelectorAll("[data-i18n-ph]").forEach(el=>{
    const key = el.getAttribute("data-i18n-ph");
    if(dict[key] !== undefined) el.setAttribute("placeholder", dict[key]);
  });
  const h1 = document.querySelector("[data-i18n-html='hero_h1']");
  if(h1){
    if(currentLang==="fr"){
      h1.innerHTML = 'Votre passerelle vers <span>les march\u00e9s chinois</span>, livr\u00e9e chez vous.';
    } else {
      h1.innerHTML = "Your bridge to <span>China's markets</span>, delivered to your door.";
    }
  }
}

