// -- Basket / Cart --
let cart = {}; // { productId: qty }
function addToCart(id){
  cart[id] = (cart[id] || 0) + 1;
  updateCartCount();
  openCart();
}
function changeQty(id, delta){
  cart[id] = (cart[id] || 0) + delta;
  if(cart[id] <= 0) delete cart[id];
  updateCartCount();
  renderCart();
}
function removeFromCart(id){
  delete cart[id];
  updateCartCount();
  renderCart();
}
function updateCartCount(){
  const count = Object.values(cart).reduce((a,b)=>a+b, 0);
  const el = document.getElementById("cartCount");
  el.textContent = count;
  el.classList.toggle("hidden", count === 0);
}
function openCart(){
  renderCart();
  document.getElementById("cartModal").classList.add("show");
}
function closeCart(){
  document.getElementById("cartModal").classList.remove("show");
}
function renderCart(){
  const ids = Object.keys(cart);
  const listEl = document.getElementById("cartItemsList");
  const emptyEl = document.getElementById("cartEmptyState");
  const totalRow = document.getElementById("cartTotalRow");
  const payInfo = document.getElementById("cartPayInfo");
  const checkoutBtn = document.getElementById("cartCheckoutBtn");

  if(ids.length === 0){
    listEl.innerHTML = "";
    emptyEl.classList.remove("hidden");
    totalRow.classList.add("hidden");
    payInfo.classList.add("hidden");
    checkoutBtn.classList.add("btn-disabled");
    checkoutBtn.removeAttribute("href");
    return;
  }
  emptyEl.classList.add("hidden");
  checkoutBtn.classList.remove("btn-disabled");

  let total = 0;
  let lines = [];
  listEl.innerHTML = ids.map(id => {
    const p = READY_PRODUCTS.find(x => x.id === id);
    const unitPrice = priceMode === "retail" ? p.retail : p.wholesale;
    const qty = cart[id];
    const lineTotal = unitPrice * qty;
    total += lineTotal;
    lines.push(`${p.name} x${qty} -- ${fmt(lineTotal)}`);
    return `
      <div class="cart-row">
        <img src="${p.img}" alt="">
        <div style="flex:1;">
          <div class="cart-row-name">${p.name}</div>
          <div class="cart-row-price">${fmt(unitPrice)} each</div>
        </div>
        <div class="cart-qty">
          <button onclick="changeQty('${id}',-1)">-</button>
          <span>${qty}</span>
          <button onclick="changeQty('${id}',1)">+</button>
        </div>
        <button class="cart-remove" onclick="removeFromCart('${id}')">Remove</button>
      </div>`;
  }).join("");

  totalRow.classList.remove("hidden");
  payInfo.classList.remove("hidden");
  document.getElementById("cartTotalAmount").textContent = fmt(total);

  const modeLabel = priceMode === "retail" ? "Retail" : "Wholesale";
  const message = `Hi J.A Services, I've paid for the following order (${modeLabel} pricing):\n\n${lines.join("\n")}\n\nTotal: ${fmt(total)}\n\nHere is my payment proof. Please confirm and arrange delivery.`;
  checkoutBtn.href = waLink(message);
}

